 const putDb=(next:Database)=>{dbRef.current=next;setDb(next);};
 const refresh=React.useCallback(async()=>{
  if(pending.current)return;const sequence=++loadSequence.current;
  try {
   const [loaded,roster]=await Promise.allSettled([inventoryRepository.load(),inventoryRepository.profiles()]);
   if(!mounted.current||sequence!==loadSequence.current||pending.current)return;
   // A failed inventory read must not suppress an independently refreshed role.
   if(roster.status==='fulfilled'){setProfiles(roster.value);const own=roster.value.find(p=>p.id===profile.id);if(own)updateProfile(own);else throw {code:'42501',message:'Team profile is unavailable.'};}
   const failures=[loaded,roster].flatMap(result=>result.status==='rejected'?[result.reason]:[]);
   const accessFailure=failures.find(error=>['permission','session'].includes(readFailure(error).kind));
   if(accessFailure)throw accessFailure;
   if(loaded.status==='rejected')throw loaded.reason;
   if(roster.status==='rejected')throw roster.reason;
   putDb(loaded.value);setLoadError(null);setAccessBlocked(false);
  } catch(e) {
   if(mounted.current&&sequence===loadSequence.current&&!pending.current){const failure=readFailure(e);setLoadError(failure);if(failure.kind==='permission'||failure.kind==='session')setAccessBlocked(true);}
   throw e;
  }
 },[profile.id,updateProfile]);
 React.useEffect(()=>{mounted.current=true;const reload=()=>void refresh().catch(()=>{});const cleanup=inventoryRepository.subscribe(reload,setLiveStatus);reload();return()=>{mounted.current=false;loadSequence.current++;cleanup();};},[refresh]);
 const retryRefresh=async()=>{if(retryPending.current||pending.current)return;retryPending.current=true;setRetrying(true);try{await refresh();}catch{}finally{retryPending.current=false;if(mounted.current)setRetrying(false);}};
 const write=async(action:()=>Promise<void>):Promise<boolean>=>{
  if(pending.current||accessBlocked)return false;pending.current=true;loadSequence.current++;setBusy(true);setError('');
  try{await action();}catch(e){setError(`${friendlyError(e)} Your change was not saved.`);setWriteErrorVersion(version=>version+1);pending.current=false;setBusy(false);void refresh().catch(()=>{});return false;}
  pending.current=false;setBusy(false);try{await refresh();}catch{setError('Your change was saved, but the latest inventory could not be loaded. Use Retry loading inventory; do not submit the change again.');}return true;
 };
 const updateSavedItem=(item:Item)=>putDb({...dbRef.current,items:dbRef.current.items.map(i=>i.id===item.id?item:i)});
