 const [editing,setEditing]=useState<Item|null>(null),[isNew,setIsNew]=useState(false);
 const commit=(next:Database):Promise<boolean>=>write(async()=>{
  const before=dbRef.current;
  if(!isAdmin(profile)){
   if(JSON.stringify(before.areas)!==JSON.stringify(next.areas)||JSON.stringify(before.locations)!==JSON.stringify(next.locations)||JSON.stringify(before.categories)!==JSON.stringify(next.categories))throw new Error('Only admins and mentors can change team configuration.');
   for(const item of next.items){const old=before.items.find(i=>i.id===item.id);if(JSON.stringify(old)!==JSON.stringify(item)&&(old?(!canEdit(profile,item.areaId)||!canEdit(profile,old.areaId)):!canCreate(profile,item.areaId)))throw new Error('You cannot edit metadata in this area.');}
   for(const item of before.items)if(!next.items.some(i=>i.id===item.id)&&!canEdit(profile,item.areaId))throw new Error('You cannot delete this item.');
  }
  await inventoryRepository.apply(before,next);
 });
 const correctQuantity=async(item:Item,quantity:number):Promise<boolean>=>{
  if(!canCount(profile)||!Number.isFinite(quantity)||quantity<0)return false;setToastPaused(false);
  return write(async()=>{const result=await inventoryRepository.quantity(item,{quantity});updateSavedItem(result.item);setQuantityToast({id:createId(),itemId:item.id,name:item.name,quantity:result.locationQuantity??result.item.quantity,locationId:item.balanceLocationId,previous:result.before,updatedAt:result.item.updatedAt,unit:item.unit});});
 };
 const adjust=async(item:Item,delta:number)=>{
  if(!canCount(profile))return;setToastPaused(false);
  await write(async()=>{const result=await inventoryRepository.quantity(item,{delta});updateSavedItem(result.item);setQuantityToast({id:createId(),itemId:item.id,name:item.name,quantity:result.locationQuantity??result.item.quantity,locationId:item.balanceLocationId,previous:result.before,updatedAt:result.item.updatedAt,unit:item.unit});});
 };
 const undoQuantity=async()=>{
  if(!quantityToast||quantityToast.undone)return;const stored=dbRef.current.items.find(i=>i.id===quantityToast.itemId);const current=stored&&quantityToast.locationId?atLocation(dbRef.current,stored,quantityToast.locationId):stored;
  if(!current||current.quantity!==quantityToast.quantity||current.updatedAt!==quantityToast.updatedAt){setQuantityToast(null);setNotice('This item has changed since that adjustment. Open its details to review the current quantity.');return;}
  await write(async()=>{const result=await inventoryRepository.quantity(current,{quantity:quantityToast.previous});updateSavedItem(result.item);setQuantityToast({...quantityToast,quantity:result.locationQuantity??result.item.quantity,undone:true});});
 };
 const verifyQuantity=async(item:Item,quantity:number):Promise<string|null>=>{
  if(!canCount(profile)||!Number.isFinite(quantity)||quantity<0)return null;
  let verified:string|null=null;
  await write(async()=>{const result=await inventoryRepository.quantity(item,{quantity,verify:true});updateSavedItem(result.item);setEditing(result.item);setQuantityToast(null);verified=result.item.lastVerified;});return verified;
 };
